# -*- coding: utf-8 -*-
from pathlib import Path
import json,html,shutil,re
root=Path.cwd();out=root/'outputs/runtime-checkpoint-48';dest=root/'publish/echoing-green/verification/fox-footsteps';dest.mkdir(parents=True,exist_ok=True)
rows=json.loads((out/'reproduce-verified.json').read_text());names={'fresh':'普通开场','warm-10':'生活10秒后','warm-60':'生活60秒后','warm-120':'生活120秒后','ambient-market':'已有晚市时','ambient-music':'已有听琴活动时','after-market':'晚市结束后','after-music':'听琴结束后','after-paper':'挂完纸笺后','retreat-edge':'退到边缘、面朝外时'}
trs=''.join(f'<tr><td>{names[x["name"]]}</td><td>{x["first"]:.2f} 秒</td><td>{x["span"]:.2f}</td><td>{"走近并完成招呼" if x["greeted"] and x["outcome"]=="completed" else html.escape(x["outcome"])}</td></tr>' for x in rows)
cards=[]
for name,title,caption in [('fox-step-a.png','迈步取样 A','四条腿继续参与步态，不受上一段舔爪残余姿态覆盖。'),('fox-step-b.png','迈步取样 B','同一次互动的另一时刻；现场数据同时核对四肢旋转和脚掌接触。'),('fox-greeting.png','走近后停下招呼','在附近街坊面前站稳，再抬爪、抬头和摇尾。'),('lamps-02s.png','约2秒','前面的灯开始发亮，后面的灯保留原有柔和底光。'),('lamps-07s.png','约7秒','暖光逐盏沿街展开。'),('lamps-13s.png','约13秒','这一轮纸灯已依次亮起，随后温和收束。')]:
 shutil.copy2(out/name,dest/name);cards.append(f'<article><h2>{title}</h2><img src="{name}" alt="{title}" loading="lazy"><p>{caption}</p></article>')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CP48 · 狐狸迈步与逐盏纸灯</title><style>body{margin:0;background:#28232e;color:#eee0ca;font:16px/1.75 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:32px 24px 70px}a{color:#e8bb7e}h1{font:36px Georgia,serif}h2{font-size:22px;color:#e4bb85}.note,article{background:#342d38;border:1px solid #655247;border-radius:12px;padding:18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(360px,1fr));gap:18px}img{width:100%;border-radius:8px}table{border-collapse:collapse;width:100%;min-width:600px}th,td{text-align:left;padding:12px;border-bottom:1px solid #655247}.scroll{overflow:auto}@media(max-width:460px){main{padding:20px 14px}.grid{grid-template-columns:1fr}h1{font-size:29px}}</style><main><a href="../../">← 回到小镇</a> · <a href="../expressive-life/">CP47 历史记录</a><h1>CP48 · 狐狸迈步，纸灯慢慢亮</h1><p>2026-11-05 · 本轮修复“狐狸招呼街坊”时四肢不动、部分连续操作后站着不响应，以及纸灯点亮过快。</p><div class="note">上轮检查验证了位置和行为状态，但漏掉了最终四肢姿态被覆盖的问题。本轮补上实际渲染关节与脚掌接触的检查，并重测集市、纸笺、听琴之后的连续操作。下方图片是实际网页取样，没有录制视频；静帧本身不等于完整动作验收。</div><h2>这次修了什么</h2><ul><li>移动时，四肢由走路步态统一控制；舔爪、伸展和抬爪在站稳后衔接。四肢按实际路程交替，支撑脚贴住真实铺装，避免身体平移而腿不动。</li><li>新招呼请求可以接过旧的退让、听琴状态。边缘恢复采用实际迈步的后退与弧线转身；前方后半段被挡住时，会先走完可安全移动的部分，再协调附近街坊让路。</li><li>必要时一位街坊走到附近停步等狐狸；同样复用已有步行路线，不瞬移、不额外召集全镇。明确要求其他人照旧时，不安排这位街坊。互动结束后恢复日常。</li><li>纸灯每隔约0.85秒开始亮起下一盏，每盏再用约1.1秒柔和增亮，整排约12秒展开。街边暖光同样分阶段增加；收尾时只淡出已经亮起的灯。</li></ul><h2>实际网页取样</h2><div class="grid">'''+''.join(cards)+'''</div><h2>连续状态检查</h2><p>下表为同一模拟器的受控复测。首移动指狐狸身体位移超过0.01单位的时间；旁边街坊有时会更早作出回应。这些是模拟时间，不是接口延迟或用户设备性能保证。位移幅度以模型单位计。</p><div class="scroll"><table><thead><tr><th>开始前的状态</th><th>狐狸首移动</th><th>最大位置变化</th><th>结果</th></tr></thead><tbody>'''+trs+'''</tbody></table></div><p>另补测了更容易卡住的“生活10秒→晚市→狐狸招呼”：实际网页里，狐狸先走出边缘，再完成招呼，约18.4模拟秒结束。此前是完全站住、反复放弃路线；失败记录保留。四肢回归同时覆盖30/60/120Hz显示节奏，核对最终关节姿态和支撑脚。</p><p>完整267项应用检查通过，最后的步态、路线与灯光修改另经相关专项检查（包含重复回归，不能相加为独立案例）。新增检查也覆盖一位街坊的临时等待和结束释放、明确不影响他人的要求、纸灯逐盏亮起与收尾。未重新做旧版83条原话的全量模型调用。</p><p>沿用原Jev接口、密钥与已批准美术，场景模型、纹理、主相机和背景音乐未替换。狐狸的可走范围复用现有广场与听琴活动的地面；未承诺全世界任意位置都可到达或所有设备的固定帧率。</p><p><a href="../../">打开小镇，输入“狐狸招呼街坊” →</a></p></main></html>'''
(dest/'index.html').write_text(page)
for path,link in [('verification/expressive-life/index.html','../fox-footsteps/'),('verification/index.html','fox-footsteps/')]:
 p=root/'publish/echoing-green'/path;s=p.read_text().replace('<b>最新 CP47：</b>','<b>CP47 历史补充：</b>')
 banner=f'<aside style="padding:18px;margin:18px 0;background:#49333b;color:#f4e5ce;border-left:3px solid #e8bc7d"><b>最新 CP48：</b>已修复狐狸四肢动画被覆盖、部分连续操作卡住，以及纸灯点亮过快。<a style="color:#f3c884" href="{link}">查看本轮实测 →</a><br>下方为历史版本记录，不能作为新版四肢步态的证明。</aside>'
 if '最新 CP48' not in s:s=re.sub(r'(<main[^>]*>)',lambda m:m[0]+banner,s,count=1)
 p.write_text(s)
print(json.dumps({'report':str(dest.relative_to(root)),'images':len(cards),'scenarios':len(rows)}))
